; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: test (Test harness (port I/O console)), starts in normal mode
; ============================================================

			org #4000

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs

ntc_start:
			di
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; main.bas 7: Print "1 started"
			dw kw_printstrvar, str0
			dw kw_printnl

			; main.bas 8: Wait
			dw p_wait_c

			; main.bas 9: Print "2 Capability LOAD"; FileSystem.Capability("LOAD"); " SAVE"; FileSystem.Capability("SAVE")
			dw fn_filesystem_capability, str1, var_filesystem_capability_capability
			dw kw_printstrvar, str2
			dw kw_printint, var_filesystem_capability_capability
			dw fn_filesystem_capability, str3, var_filesystem_capability_capability
			dw kw_printstrvar, str4
			dw kw_printint, var_filesystem_capability_capability
			dw kw_printnl

			; main.bas 10: Wait
			dw p_wait_c

			; main.bas 11: Print "3 Devices: "; FileSystem.Devices()
			dw p_filesystem_devices_c
			dw kw_printstrvar, str5
			dw kw_printstrvar, var_filesystem_devices_devices
			dw kw_printnl

			; main.bas 12: Wait
			dw p_wait_c

			; main.bas 13: Print "4 CurrentDevice: "; FileSystem.CurrentDevice(); "  Volume: "; FileSystem.CurrentVolume()
			dw p_filesystem_currentdevice_c
			dw kw_printstrvar, str6
			dw kw_printstrvar, var_filesystem_currentdevice_currentdevice
			dw p_filesystem_currentvolume_c
			dw kw_printstrvar, str7
			dw kw_printstrvar, var_filesystem_currentvolume_currentvolume
			dw kw_printnl

			; main.bas 14: Wait
			dw p_wait_c

			; main.bas 15: For i = 0 To 9 : a(i) = 1000 - i * 50 : Next
			dw kw_ztov, var_i
for1_t:
			dw kw_mulvl, var_i, 50, tmp2
			dw kw_sublv, 1000, tmp2, tmp1
			dw kw_aset, arr_a, var_i, tmp1
			dw kw_next1l_n, var_i, 9, for1_t
for1_e:

			; main.bas 16: Print "5 Save STEP.DAT..."
			dw kw_printstrvar, str8
			dw kw_printnl

			; main.bas 17: Wait
			dw p_wait_c

			; main.bas 18: r = FileSystem.Save("STEP.DAT", VarPtr(a), 20)
			dw p_filesystem_save_c, str9, vp_arr_a, lit_20
			dw kw_vtov, var_filesystem_save_save, var_r

			; main.bas 19: Print "  Save gave"; r
			dw kw_printstrvar, str10
			dw kw_printint, var_r
			dw kw_printnl

			; main.bas 20: Wait
			dw p_wait_c

			; main.bas 21: Print "6 Load STEP.DAT..."
			dw kw_printstrvar, str11
			dw kw_printnl

			; main.bas 22: Wait
			dw p_wait_c

			; main.bas 23: r = FileSystem.Load("STEP.DAT", VarPtr(b), 20)
			dw p_filesystem_load_c, str9, vp_arr_b, lit_20
			dw kw_vtov, var_filesystem_load_load, var_r

			; main.bas 24: Print "  Load gave"; r; ", "; b(0); " ... "; b(9)
			dw kw_printstrvar, str12
			dw kw_printint, var_r
			dw kw_printstrvar, str13
			dw kw_printint, arr_b
			dw kw_printstrvar, str14
			dw kw_printint, arr_b+18
			dw kw_printnl

			; main.bas 25: Print "7 done - press a key to end"
			dw kw_printstrvar, str15
			dw kw_printnl

			; main.bas 26: Wait
			dw p_wait_c

			; main.bas 27: End
			dw kw_stop

; ============================================================
; sub wait (normal mode)
; ============================================================

p_wait:

			; main.bas 30: Print "  (press a key)"
			dw kw_printstrvar, str16
			dw kw_printnl

			; main.bas 31: Do While Inkey <> 0 : Loop
do2_t:
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do2_e
			dw do2_t_go
do2_e:

			; main.bas 32: Do : Frame : Loop Until Inkey <> 0
do3_t:
			dw kw_frame
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do3_t
do3_e:
			dw p_wait_r

; ============================================================
; function load (normal mode)
; ============================================================

p_filesystem_load:

			; FileSystem.cls 39: Load = NotSupported
			dw kw_ltov, -1, var_filesystem_load_load
			dw p_filesystem_load_r

; ============================================================
; function save (normal mode)
; ============================================================

p_filesystem_save:

			; FileSystem.cls 43: Save = NotSupported
			dw kw_ltov, -1, var_filesystem_save_save
			dw p_filesystem_save_r

; ============================================================
; function devices (normal mode)
; ============================================================

p_filesystem_devices:

			; FileSystem.cls 102: Devices = ""
			dw kw_strcpy, var_filesystem_devices_devices, str17
			dw p_filesystem_devices_r

; ============================================================
; function currentdevice (normal mode)
; ============================================================

p_filesystem_currentdevice:

			; FileSystem.cls 105: CurrentDevice = ""
			dw kw_strcpy, var_filesystem_currentdevice_currentdevice, str17
			dw p_filesystem_currentdevice_r

; ============================================================
; function currentvolume (normal mode)
; ============================================================

p_filesystem_currentvolume:

			; FileSystem.cls 114: CurrentVolume = ""
			dw kw_strcpy, var_filesystem_currentvolume_currentvolume, str17
			dw p_filesystem_currentvolume_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

do2_t_go:			ld sp, do2_t
			jp ntc_xn

p_wait_c:		; call wait (normal)
			ld (p_wait_rs), sp
			ld sp, p_wait
			jp ntc_xn
p_wait_r:		; end of wait
			ld sp, (p_wait_rs)
			jp ntc_xn
p_filesystem_load_c:		; call load (normal)
			pop hl			; name
			ld de, var_filesystem_load_name
			ld b, 40
p_filesystem_load_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_filesystem_load_si0_e
			inc hl
			inc de
			djnz p_filesystem_load_si0
			xor a
			ld (de), a
p_filesystem_load_si0_e:
			pop hl			; addr
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_filesystem_load_addr), de
			pop hl			; maxlen
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_filesystem_load_maxlen), de
			ld hl, 0
			ld (var_filesystem_load_load), hl
			ld (p_filesystem_load_rs), sp
			ld sp, p_filesystem_load
			jp ntc_xn
p_filesystem_load_r:		; end of load
			ld sp, (p_filesystem_load_rs)
			jp ntc_xn
p_filesystem_save_c:		; call save (normal)
			pop hl			; name
			ld de, var_filesystem_save_name
			ld b, 40
p_filesystem_save_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_filesystem_save_si0_e
			inc hl
			inc de
			djnz p_filesystem_save_si0
			xor a
			ld (de), a
p_filesystem_save_si0_e:
			pop hl			; addr
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_filesystem_save_addr), de
			pop hl			; length
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_filesystem_save_length), de
			ld hl, 0
			ld (var_filesystem_save_save), hl
			ld (p_filesystem_save_rs), sp
			ld sp, p_filesystem_save
			jp ntc_xn
p_filesystem_save_r:		; end of save
			ld sp, (p_filesystem_save_rs)
			jp ntc_xn
p_filesystem_devices_c:		; call devices (normal)
			xor a
			ld (var_filesystem_devices_devices), a
			ld (p_filesystem_devices_rs), sp
			ld sp, p_filesystem_devices
			jp ntc_xn
p_filesystem_devices_r:		; end of devices
			ld sp, (p_filesystem_devices_rs)
			jp ntc_xn
p_filesystem_currentdevice_c:		; call currentdevice (normal)
			xor a
			ld (var_filesystem_currentdevice_currentdevice), a
			ld (p_filesystem_currentdevice_rs), sp
			ld sp, p_filesystem_currentdevice
			jp ntc_xn
p_filesystem_currentdevice_r:		; end of currentdevice
			ld sp, (p_filesystem_currentdevice_rs)
			jp ntc_xn
p_filesystem_currentvolume_c:		; call currentvolume (normal)
			xor a
			ld (var_filesystem_currentvolume_currentvolume), a
			ld (p_filesystem_currentvolume_rs), sp
			ld sp, p_filesystem_currentvolume
			jp ntc_xn
p_filesystem_currentvolume_r:		; end of currentvolume
			ld sp, (p_filesystem_currentvolume_rs)
			jp ntc_xn

; ============================================================
; Inline assembly (#asm ... #endasm)
; ============================================================

fn_filesystem_capability:		; function capability (asm keyword), FileSystem.cls line 29
            pop hl		; FileSystem.cls 30
            pop de		; FileSystem.cls 31
            ld bc, fn_filesystem_capability_caps		; FileSystem.cls 32
            jp ntc_capfind		; FileSystem.cls 33
fn_filesystem_capability_caps:       db 0		; FileSystem.cls 34
			ret			; end of #asm


; ============================================================
; Variables
; ============================================================

var_filesystem_capability_capability:			dw 0
			db 40			; capacity
var_filesystem_devices_devices:			ds 41
			db 40			; capacity
var_filesystem_currentdevice_currentdevice:			ds 41
			db 40			; capacity
var_filesystem_currentvolume_currentvolume:			ds 41
var_i:			dw 0
var_r:			dw 0
var_filesystem_save_save:			dw 0
var_filesystem_load_load:			dw 0
p_wait_rs:			dw 0
p_filesystem_load_rs:			dw 0
			db 40			; capacity
var_filesystem_load_name:			ds 41
var_filesystem_load_addr:			dw 0
var_filesystem_load_maxlen:			dw 0
p_filesystem_save_rs:			dw 0
			db 40			; capacity
var_filesystem_save_name:			ds 41
var_filesystem_save_addr:			dw 0
var_filesystem_save_length:			dw 0
p_filesystem_devices_rs:			dw 0
p_filesystem_currentdevice_rs:			dw 0
p_filesystem_currentvolume_rs:			dw 0
tmp0:			dw 0
tmp1:			dw 0
tmp2:			dw 0

; numbers passed by address (read only)
vp_arr_a:			dw arr_a
lit_20:			dw 20
vp_arr_b:			dw arr_b
llit_m1:			dw 65535, 65535

; ============================================================
; Strings
; ============================================================

str0:			db "1 started", 0
str1:			db "LOAD", 0
str2:			db "2 Capability LOAD", 0
str3:			db "SAVE", 0
str4:			db " SAVE", 0
str5:			db "3 Devices: ", 0
str6:			db "4 CurrentDevice: ", 0
str7:			db "  Volume: ", 0
str8:			db "5 Save STEP.DAT...", 0
str9:			db "STEP.DAT", 0
str10:			db "  Save gave", 0
str11:			db "6 Load STEP.DAT...", 0
str12:			db "  Load gave", 0
str13:			db ", ", 0
str14:			db " ... ", 0
str15:			db "7 done - press a key to end", 0
str16:			db "  (press a key)", 0
